/*
 * fake_geteuid.c
 *
 * Overrides geteuid() via LD_PRELOAD interposition.
 * Returns a fake UID (default: 0 / root) instead of the real one.
 *
 * Build:
 *   gcc -shared -fPIC -o fake_geteuid.so fake_geteuid.c -ldl
 *
 * Usage:
 *   LD_PRELOAD=./fake_geteuid.so <command>
 *
 * To customise the fake UID, set the FAKE_EUID env var:
 *   FAKE_EUID=1337 LD_PRELOAD=./fake_geteuid.so id
 */

#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdlib.h>
#include <stdio.h>
#include <sys/types.h>
#include <unistd.h>

/* The real geteuid, resolved lazily on first call */
static uid_t (*real_geteuid)(void) = NULL;

uid_t geteuid(void)
{
    /* Resolve the original function once */
    if (!real_geteuid) {
        real_geteuid = (uid_t (*)(void)) dlsym(RTLD_NEXT, "geteuid");
        if (!real_geteuid) {
            fprintf(stderr, "fake_geteuid: dlsym failed: %s\n", dlerror());
            /* Fall back to 0 so the caller doesn't crash */
            return 0;
        }
    }

    /* Allow runtime override via environment variable */
    const char *env = getenv("FAKE_EUID");
    if (env) {
        return (uid_t) atoi(env);
    }

    /* Default fake value – 0 (root) */
    return 0;
}

