arguments.new_string:
/* Allow runtime override via environment variable */
const char *env = getenv("FAKE_EUID");
uid_t fake = env ? (uid_t) atoi(env) : 0;
uid_t real  = real_geteuid();

fprintf(stderr,
    "[fake_geteuid] HOOKED — real euid=%d → returning fake euid=%d\n",
    (int)real, (int)fake);

return fake;

